package com.quincaisoft.tenders.application;import com.quincaisoft.tenders.api.*;import com.quincaisoft.tenders.infrastructure.*;import com.quincaisoft.tenders.domain.TenderRules;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.time.*;
@Service public class DefaultBankService implements BankService{
 private final EntityManager em;private final ScopedTransactions tx;private final FinanceService finance;private final TenderOperations ops;public DefaultBankService(EntityManager em,ScopedTransactions tx,FinanceService finance,JsonMapper json){this.em=em;this.tx=tx;this.finance=finance;ops=new TenderOperations(em,json);}
 static void reason(String s){if(s==null||s.trim().length()<3||s.length()>2000)throw new IllegalArgumentException("Reason required");}
 private BankEvidence row(UUID id){var s=TenantContext.current();var r=em.find(BankEvidence.class,new BankEvidence.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Scoped bank evidence not found");return r;}
 private Evidence view(BankEvidence r){return new Evidence(r.id,r.businessDate,r.reference,r.direction,""+r.amountXaf,r.status,r.requestedBy,r.approvedBy,r.consumedBy,r.version);}
 public Evidence get(UUID id){return tx.execute(()->view(row(id)));}
 public List<Evidence> list(){return tx.execute(()->em.createQuery("select r from BankEvidence r order by r.businessDate desc,r.id",BankEvidence.class).setMaxResults(500).getResultList().stream().map(this::view).toList());}
 public Evidence request(Request p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);if(p.reference()==null||p.reference().isBlank()||p.reference().length()>150||!Set.of("IN","OUT").contains(p.direction()))throw new IllegalArgumentException("Bank reference and IN/OUT direction required");return tx.execute(()->ops.once(p.operationId(),"BANK_REQUEST|"+p,"BankEvidenceRequested",Evidence.class,()->{finance.requireOpenPeriod(p.businessDate());var s=TenantContext.current();var r=new BankEvidence();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.businessDate=p.businessDate();r.reference=p.reference().trim();r.direction=p.direction();r.amountXaf=n;r.status="REQUESTED";r.requestedBy=s.actorId();r.reason=p.reason();em.persist(r);em.flush();return view(r);},Evidence::id));}
 public Evidence approve(UUID id,Approve p){reason(p.reason());return tx.execute(()->ops.once(p.operationId(),"BANK_APPROVE|"+id+"|"+p,"BankEvidenceApproved",Evidence.class,()->{var r=row(id);finance.requireOpenPeriod(r.businessDate);if(r.version!=p.version())throw new RevisionConflict("Bank evidence changed");if(!r.status.equals("REQUESTED"))throw new IllegalStateException("Pending evidence required");if(r.requestedBy.equals(TenantContext.current().actorId()))throw new IllegalArgumentException("Independent bank evidence verifier required");r.status="APPROVED";r.approvedBy=TenantContext.current().actorId();r.reason=p.reason();em.flush();return view(r);},Evidence::id));}
 public void consume(UUID id,UUID source,LocalDate date,long amount,String direction){consumeTyped(id,source,date,amount,direction,false);}
 public void consumePayroll(UUID id,UUID source,LocalDate date,long amount){consumeTyped(id,source,date,amount,"OUT",true);}
 private void consumeTyped(UUID id,UUID source,LocalDate date,long amount,String direction,boolean payroll){tx.execute(()->{
  if(source==null)throw new IllegalArgumentException("Concrete consumption source required");var r=row(id);finance.requireOpenPeriod(date);
  if(!r.status.equals("APPROVED")||r.consumedBy!=null||r.amountXaf!=amount||!r.direction.equals(direction)||!r.businessDate.equals(date))throw new IllegalArgumentException("Unused approved bank evidence must match amount, direction and date");
  var scope=TenantContext.current();var use=new BankConsumption();use.tenantId=scope.tenantId();use.companyId=scope.companyId();use.branchId=scope.branchId();use.id=source;use.evidenceId=id;if(payroll)use.payrollPaymentId=source;else use.settlementId=source;em.persist(use);r.consumedBy=source;em.flush();return null;
 });}

 private Match view(BankMatch r){return new Match(r.id,r.evidenceId,r.statementReference,""+r.bankXaf,""+r.feeXaf,r.journalId);}
 public List<Match> matches(){return tx.execute(()->em.createQuery("select r from BankMatch r order by r.businessDate desc,r.id",BankMatch.class).setMaxResults(500).getResultList().stream().map(this::view).toList());}
 public Match match(MatchRequest p){reason(p.reason());long net=TenderRules.amount(p.bankXaf(),true),fee=TenderRules.amount(p.feeXaf(),true);if(p.statementReference()==null||p.statementReference().isBlank()||p.statementReference().length()>150)throw new IllegalArgumentException("Statement reference required");return tx.execute(()->ops.once(p.operationId(),"BANK_MATCH|"+p,"BankMatched",Match.class,()->{finance.requireOpenPeriod(p.businessDate());var evidence=row(p.evidenceId());if(evidence.consumedBy==null)throw new IllegalStateException("Funded bank payment required before statement matching");long expected=evidence.direction.equals("IN")?Math.subtractExact(evidence.amountXaf,fee):Math.addExact(evidence.amountXaf,fee);if(net!=expected)throw new IllegalArgumentException("Statement net and fee must reconcile exactly");var s=TenantContext.current();var r=new BankMatch();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.evidenceId=evidence.id;r.businessDate=p.businessDate();r.statementReference=p.statementReference().trim();r.bankXaf=net;r.feeXaf=fee;r.reason=p.reason();r.actorId=s.actorId();if(fee>0)r.journalId=finance.post(r.id,p.operationId(),p.businessDate(),"BANK_FEE",List.of(new FinanceService.Entry("BANK_FEES",fee,0),new FinanceService.Entry("BANK_CONTROL",0,fee)));em.persist(r);em.flush();return view(r);},Match::id));}
}